package app.philab.common.data.datasource.dto

import kotlinx.serialization.Serializable

/** Shape of assets/phi_table.json (generated by tools/phi_table.py, checked against the photo of the table). */
@Serializable
data class PhiTableDto(
    val title: String,
    val source: String,
    val definition: String = "",
    val zMin: Double,
    val zStep: Double,
    val count: Int,
    /** Values exactly as printed: "0.5000", "0.90147", "0.9998215" — trailing zeros keep the precision. */
    val values: List<String>,
)
